import numpy as np
from scipy.optimize import least_squares
def model(w):
    C=np.cos(w*t); S=np.sin(w*t)
    base=np.column_stack([np.ones_like(t),x,v,x**2,v**2,v**3,np.exp(-x),np.exp(-v),np.cos(x),np.sin(v)])
    return np.column_stack([base,C,S,x*C,v*C,x*S,v*S,np.cos(v)*C])
def resid(w):
    X=model(w)
    cc,_,_,_=np.linalg.lstsq(X,dv_dt,rcond=None)
    return dv_dt-X@cc
bestr=None
for w0 in np.linspace(0.2,1.5,14):
    r=least_squares(lambda p: resid(p[0]), [w0])
    val=np.mean(r.fun**2)/np.var(dv_dt)
    if bestr is None or val<bestr[0]: bestr=(val,r.x[0])
print(bestr)

